CREATE TABLE categories (
  ledger_id TEXT NOT NULL REFERENCES ledgers(id),
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),
  name_key TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
  PRIMARY KEY(ledger_id,name_key)
);
CREATE TABLE category_aliases (ledger_id TEXT NOT NULL REFERENCES ledgers(id), name TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(ledger_id,name), CHECK(name<>target));
CREATE TRIGGER category_alias_transaction_insert AFTER INSERT ON transactions WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE transactions SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND id=NEW.id; END;
CREATE TRIGGER category_alias_transaction_update AFTER UPDATE OF category ON transactions WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE transactions SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND id=NEW.id; END;
CREATE TRIGGER category_alias_annotation_insert BEFORE INSERT ON annotation_revisions WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN SELECT RAISE(ABORT,'category was renamed; refresh categories'); END;
CREATE TRIGGER category_alias_budget_allocations_insert AFTER INSERT ON budget_allocations WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_allocations SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND month=NEW.month; END;
CREATE TRIGGER category_alias_budget_allocations_update AFTER UPDATE OF category ON budget_allocations WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_allocations SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND month=NEW.month; END;
CREATE TRIGGER category_alias_budget_targets_insert AFTER INSERT ON budget_targets WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_targets SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category; END;
CREATE TRIGGER category_alias_budget_targets_update AFTER UPDATE OF category ON budget_targets WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_targets SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category; END;
CREATE TRIGGER category_alias_budget_tracking_plans_insert AFTER INSERT ON budget_tracking_plans WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_tracking_plans SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND month=NEW.month AND direction=NEW.direction; END;
CREATE TRIGGER category_alias_budget_tracking_plans_update AFTER UPDATE OF category ON budget_tracking_plans WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_tracking_plans SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND month=NEW.month AND direction=NEW.direction; END;
CREATE TRIGGER category_alias_budget_rollover_policies_insert AFTER INSERT ON budget_rollover_policies WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_rollover_policies SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND effective_month=NEW.effective_month; END;
CREATE TRIGGER category_alias_budget_rollover_policies_update AFTER UPDATE OF category ON budget_rollover_policies WHEN EXISTS(SELECT 1 FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) BEGIN UPDATE budget_rollover_policies SET category=(SELECT target FROM category_aliases WHERE ledger_id=NEW.ledger_id AND name=NEW.category) WHERE ledger_id=NEW.ledger_id AND category=NEW.category AND effective_month=NEW.effective_month; END;
